export const auth = {
  async register(body) {
    const r = await req('/api/auth/register', { method: 'POST', body: JSON.stringify(body) });
    if (r && r.token) store.setItem('apex_token', r.token);
    return r;
  },
  async login(body) {
    const r = await req('/api/auth/login', { method: 'POST', body: JSON.stringify(body) });
    if (r && r.token) store.setItem('apex_token', r.token);
    return r;
  },
  async me() { if (!token()) return null; try { return await req('/api/auth/me'); } catch (e) { return null; } },
  async logout() { store.removeItem('apex_token'); },
  async currentUser() { return auth.me(); },
};

export const files = {
  async upload(file) {
    const fd = new FormData();
    fd.append('file', file);
    const headers = {};
    const t = token();
    if (t) headers['Authorization'] = 'Bearer ' + t;
    const res = await fetch(API_URL + '/api/files', { method: 'POST', body: fd, headers });
    if (!res.ok) throw new Error('Upload failed');
    return res.json();
  },
};

export const events = {
  subscribe(cb) {
    const es = new EventSource(API_URL + '/api/events');
    es.onmessage = (e) => { try { cb(JSON.parse(e.data)); } catch (_) {} };
    return () => es.close();
  },
};

